input.script:
# First, fetch all pages of orders for 2026-03
first_page = list_orders({ month: "2026-03", page: 1 })

remaining_pages = for page in list.range(2, first_page.total_pages + 1) {
    result = boundary retry 2 { return list_orders({ month: "2026-03", page }) } catch err {
        return fail("LIST_FAILED", err.message)
    }
    return result.items
}

all_items = fold acc = first_page.items for page_items in remaining_pages {
    return acc + page_items
}

# Now get details for each order — runs concurrently
orders = for item in all_items {
    order = boundary retry 2 { return get_order({ id: item.id }) } catch err {
        return fail("ORDER_FAILED", err.message)
    }
    skip if order.status != "completed"
    customer = boundary retry 2 { return get_customer({ id: item.customer_id }) } catch err {
        return fail("CUSTOMER_FAILED", err.message)
    }
    return { amount: order.amount_cents, region: customer.region }
}

# Aggregate by region
na_total = fold acc = 0 for o in orders {
    return acc + o.amount if o.region == "NA" else acc
}

eu_total = fold acc = 0 for o in orders {
    return acc + o.amount if o.region == "EU" else acc
}

apac_total = fold acc = 0 for o in orders {
    return acc + o.amount if o.region == "APAC" else acc
}

return { NA: na_total, EU: eu_total, APAC: apac_total }
